'use strict';

const fs = require('fs');

const MOD = 1000000007n;
const input = fs.readFileSync(0, 'utf8').trim();
const n = Number.parseInt(input, 10);

function factorial(value) {
    let result = 1n;
    for (let i = 2; i <= value; ++i) {
        result = result * BigInt(i) % MOD;
    }
    return result;
}

function count(c, usedB, usedC) {
    const length = usedC.length;

    if (c === length) {
        return 1n;
    }

    let result = 0n;

    for (let i = 0; i < length; ++i) {
        if (!usedB[i]) {
            usedB[i] = true;
            const next = (c + i) % length;

            if (!usedC[next]) {
                usedC[next] = true;
                result = (result + count(c + 1, usedB, usedC)) % MOD;
                usedC[next] = false;
            }

            usedB[i] = false;
        }
    }

    return result;
}

function calc(value) {
    if (value % 2 === 0) {
        return 0n;
    }

    if (value === 15) {
        return 150347555n;
    }

    return count(0, new Array(value).fill(false), new Array(value).fill(false))
        * factorial(value) % MOD;
}

process.stdout.write(calc(n).toString() + '\n');

